import java.math.BigInteger;

@SpendingValidator
class SimpleSpending {
    @Param static byte[] authorizedSigner;

    @Entrypoint
    static boolean validate(PlutusData datum, PlutusData redeemer, ScriptContext ctx) {
        PlutusData txInfo = ContextsLib.getTxInfo(ctx);
        return ContextsLib.signedBy(txInfo, authorizedSigner);
    }
}

import java.math.BigInteger;

@SpendingValidator
class VestingValidator {
    record VestingDatum(PlutusData beneficiary, PlutusData deadline) {}

    static boolean isPastDeadline(BigInteger currentTime, BigInteger deadline) {
        return currentTime > deadline;
    }

    @Entrypoint
    static boolean validate(VestingDatum datum, PlutusData redeemer, ScriptContext ctx) {
        PlutusData txInfo = ContextsLib.getTxInfo(ctx);
        PlutusData pkh = datum.beneficiary();
        return ContextsLib.signedBy(txInfo, pkh);
    }
}

import java.math.BigInteger;

@MintingValidator
class MintingPolicy {
    sealed interface Action {
        record Mint(BigInteger amount) implements Action {}
        record Burn(BigInteger amount) implements Action {}
    }

    static boolean validateMint(BigInteger amount) {
        return amount > 0;
    }

    static boolean validateBurn(BigInteger amount) {
        return amount < 0;
    }

    @Entrypoint
    static boolean validate(PlutusData redeemer, ScriptContext ctx) {
        BigInteger mintAmount = 1;
        return validateMint(mintAmount);
    }
}
